sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          if (current.complainant_name != '' && current.complainant_name.first_name != '') {
			template.print(current.complainant_name.first_name);
			return;
		  }

		  if (current.initial_review.principal_party != '' && current.initial_review.principal_party.first_name != '') {
			template.print(current.initial_review.principal_party.first_name);
		  }

})(current, template, email, email_action, event);
